    description:
      "VLC เต็มระดับแล้วแต่วิดีโอยังเบาอยู่? VLC มีฟีเจอร์บูสต์ในตัวถึง 200% — และยังสามารถเพิ่มได้อีกด้วยตัวควบคุมระดับเสียงแยกแอป",
