    description: "ลำโพงหรือช่องหนึ่งหยุดทำงานหลังจากอัปเดตเป็น macOS Tahoe? เริ่มต้นด้วยแถบเลื่อนความสมดุลของเสียง จากนั้นรีเซ็ต Core Audio ลองใช้เซฟโหมด และตัดฮาร์ดแวร์ออก คู่มือการแก้ไขปัญหาที่ชัดเจน",
