    description: "แก้ไขเสียงแจ้งเตือนบนเดสก์ท็อป WhatsApp และ Telegram ที่ดังเกินไปใน Mac ของคุณ เริ่มต้นด้วยการตั้งค่าในตัวของแต่ละแอป จากนั้นลดหรือปิดเสียงทั้งแอปเมื่อ macOS ไม่สามารถควบคุมแอปได้",
    date: "2026-07-23",
